// Twilio sends form-encoded data
const body = $input.first().json;

// Extract the incoming WhatsApp message body and sender
const rawMessage = body.Body || '';
const fromNumber = body.From || '';

// Normalize the phone number to create a consistent session ID
// Format: 'whatsapp:+923001234567' -> 'wp_923001234567'
const sessionId = 'wp_' + fromNumber.replace('whatsapp:', '').replace('+', '').replace(/\s/g, '');

const isFirstMessage = body.NumMedia === '0' && rawMessage.length > 0;

return [{
  json: {
    session_id: sessionId,
    message: rawMessage,
    from_number: fromNumber,
    is_first_message: isFirstMessage
  }
}];

const msg = $input.first().json.message.toLowerCase().trim();
const sessionId = $input.first().json.session_id;

// Detect consent affirmation in Roman Urdu or English
const affirmative = ['haan', 'han', 'yes', 'y', 'ok', 'okay', 'theek hai', 'bilkul', 'zaroor'];
const isConsent = affirmative.some(w => msg.includes(w));

return [{
  json: {
    session_id: sessionId,
    memory: true,
    mood_logging: isConsent
  }
}];

