const data = $input.first().json;

// Clean the reply for WhatsApp formatting
// WhatsApp supports *bold* and _italic_ but not HTML
let reply = data.reply || 'Koi reply nahi mila. Dobara try karein.';

// Remove HTML tags if any slipped through
reply = reply.replace(/<[^>]*>/g, '');

// Replace markdown bold with WhatsApp bold
reply = reply.replace(/\*\*(.*?)\*\*/g, '*$1*');

// Truncate if too long (WhatsApp limit ~1600 chars)
if (reply.length > 1500) {
  reply = reply.substring(0, 1497) + '...';
}

return [{ json: { reply } }];
